import React, { useState, useEffect } from "react";
import styles from "./Banner.module.css";
import fetchMovie, { requests } from "../../../movieList";

function Banner() {
  const [movie, setMovie] = useState({ results: [] });
  const [banner, setBanner] = useState({});
  const IMAGE_BASE_URL = "https://image.tmdb.org/t/p/original";

  useEffect(() => {
    async function loadMovie() {
      const data = await fetchMovie(requests.fetchNetflixOriginals);
      setMovie(data);
    }
    loadMovie();
  }, []);

  useEffect(() => {
    if (movie.results.length > 0) {
      setBanner(
        movie.results[Math.floor(Math.random() * movie.results.length)]
      );
      console.log(movie);
    }
  }, [movie]);

  console.log(banner);
  return (
    <div>
      <img
        className={styles.img}
        src={`${IMAGE_BASE_URL}${banner["backdrop_path"]}`}
        alt=""
      />
      <div>
        <h1>{banner.name}</h1>
        <div>
          <div>
            <button></button>
            <button></button>
          </div>
          <p></p>
        </div>
      </div>
    </div>
  );
}

export default Banner;
